  name: 'percent',
  evaluate: (ctx) => {
    const hash = this.hash(ctx.userId ?? '');
    return (hash % 100) < config.percentage!;
  },
};

registry.register('percent', () => percentStrategy);

engine.evaluate('new-checkout', { userId: 'user-123', region: 'US' }, {
  strategy: 'percent',
  percentage: 10,
